<script setup lang="ts">
import {useProductivityStore} from '~/stores/productivity'; import type {Priority} from '~/types/domain'; const store=useProductivityStore(); const open=ref(false); const editing=ref<string|null>(null); const title=ref(''); const desc=ref(''); const priority=ref<Priority>('medium'); const deadline=ref('');
const save=()=>{if(!title.value.trim())return;if(editing.value)store.updateGoal(editing.value,{title:title.value,description:desc.value,priority:priority.value,deadline:deadline.value||undefined});else store.addGoal({title:title.value,description:desc.value,priority:priority.value,deadline:deadline.value||undefined});open.value=false;editing.value=null;title.value='';desc.value='';deadline.value=''}; const edit=(g:any)=>{editing.value=g.id;title.value=g.title;desc.value=g.description;priority.value=g.priority;deadline.value=g.deadline||'';open.value=true}; const stats=(g:any)=>{const tasks=store.tasks.filter(t=>t.goalId===g.id);return {total:tasks.length,done:tasks.filter(t=>t.status==='completed').length}}
</script>
<template><div class="space-y-5"><div class="flex justify-between"><div><h1 class="text-2xl font-black">اهداف</h1><p class="text-gray-500">هدف فقط یک درصد نیست؛ باید به پروژه و کارهای قابل اجرا وصل باشد.</p></div><UButton icon="i-lucide-plus" @click="open=true">هدف جدید</UButton></div><div class="grid md:grid-cols-2 gap-4"><UCard v-for="g in store.goals" :key="g.id"><template #header><div class="flex justify-between gap-2"><b>{{g.title}}</b><div class="flex"><UButton icon="i-lucide-pencil" variant="ghost" size="xs" @click="edit(g)"/><UButton icon="i-lucide-trash-2" variant="ghost" size="xs" color="error" @click="store.deleteGoal(g.id)"/></div></div></template><p class="text-sm text-gray-500">{{g.description}}</p><div class="mt-5 flex justify-between"><span>پیشرفت</span><b>{{store.goalEffectiveProgress(g.id)}}٪</b></div><USlider :model-value="g.progress" class="mt-2" @update:model-value="v=>store.updateGoal(g.id,{progress:typeof v==='number'?v:g.progress})"/><div class="grid grid-cols-3 gap-2 mt-4 text-center"><div class="p-3 rounded-xl bg-gray-50 dark:bg-gray-800/50"><b>{{stats(g).done}}</b><p class="text-xs text-gray-500">کار انجام‌شده</p></div><div class="p-3 rounded-xl bg-gray-50 dark:bg-gray-800/50"><b>{{stats(g).total}}</b><p class="text-xs text-gray-500">کار متصل</p></div><div class="p-3 rounded-xl bg-gray-50 dark:bg-gray-800/50"><b>{{g.deadline||'—'}}</b><p class="text-xs text-gray-500">موعد</p></div></div></UCard></div><UModal v-model:open="open"><template #content><UCard><template #header>{{editing?'ویرایش هدف':'هدف جدید'}}</template><div class="space-y-4"><UInput v-model="title" placeholder="عنوان هدف"/><UTextarea v-model="desc" placeholder="چرا این هدف مهم است؟"/><USelect v-model="priority" :items="['low','medium','high','critical']"/><UInput v-model="deadline" type="date"/><div class="flex justify-end gap-2"><UButton variant="ghost" @click="open=false">انصراف</UButton><UButton @click="save">ذخیره</UButton></div></div></UCard></template></UModal></div></template>
